/* ================= illustrated 도깨비, bosses and challenge ghosts: one picture each, facing right =================
   frames for the walk bob and the white hit flash are baked from these in c_render */
const FOE_SPRITE_SRC = {
  foe_f0: 'data:image/webp;base64,',
  foe_f1: 'data:image/webp;base64,',
  foe_f2: 'data:image/webp;base64,',
  foe_f3: 'data:image/webp;base64,',
  foe_f4: 'data:image/webp;base64,',
  foe_f5: 'data:image/webp;base64,',
  foe_f6: 'data:image/webp;base64,',
  foe_f7: 'data:image/webp;base64,',
  boss_beom: 'data:image/webp;base64,',
  boss_gumiho: 'data:image/webp;base64,',
  boss_imugi: 'data:image/webp;base64,',
  boss_bulgasari: 'data:image/webp;base64,',
  boss_geumdwaeji: 'data:image/webp;base64,',
  boss_daejeok: 'data:image/webp;base64,',
  boss_heukryong: 'data:image/webp;base64,',
  boss_yeomra: 'data:image/webp;base64,',
  chal_eodum: 'data:image/webp;base64,',
  chal_dueok: 'data:image/webp;base64,',
  chal_gangcheol: 'data:image/webp;base64,',
  chal_jine: 'data:image/webp;base64,',
  chal_yacha: 'data:image/webp;base64,',
};
const FOE_SPRITES = {};
for (const id in FOE_SPRITE_SRC) { const im = new Image(); im.onload = () => { if (typeof PORTRAIT_CACHE !== 'undefined') PORTRAIT_CACHE.clear(); }; im.src = FOE_SPRITE_SRC[id]; FOE_SPRITES[id] = im; }
const foeSpriteReady = id => { const S = FOE_SPRITES[id]; return !!S && S.complete && S.naturalWidth > 0; };

